//! 🦴️ Skins own complete source references and ordered joint memberships.
use super::*;
pub(super) fn project(write:&mut Write<'_,'_>,skins:&[GltfSkin])->Result<(), ValueError>{write.check(skins.len())?;for(position,skin)in skins.iter().enumerate(){let [inverse_high,inverse_low]=optional_index(skin.inverse_bind_matrices);let [skeleton_high,skeleton_low]=optional_index(skin.skeleton);let [extension,extra]=write.extras(&skin.extensions,&skin.extras)?;let key=write.insert("gltf_skin",&[Cell::Integer(1),ordinal(position)?,inverse_high,inverse_low,skeleton_high,skeleton_low,text(&skin.name),extension,extra])?;write.check(skin.joints.len())?;for(position,joint)in skin.joints.iter().enumerate(){let [high,low]=index(*joint);write.insert("gltf_skin_joint",&[Cell::Integer(key),ordinal(position)?,high,low])?;}}Ok(())}
pub(super) fn reconstruct(read:&mut Read<'_,'_,'_>)->Result<Vec<GltfSkin>, ValueError>{let rows=read.rows("gltf_skin",1,1,2)?;let mut skins=owned(read.reserve(rows.len())?);for row in rows{let mut skin=owned(GltfSkin::default());let value=skin.as_mut();value.inverse_bind_matrices=read.optional_index(row,3)?;value.skeleton=read.optional_index(row,5)?;value.name=read.optional_text(row,7)?;value.extensions=read.json(row,8)?;value.extras=read.json(row,9)?;let rows=read.rows("gltf_skin_joint",1,row.rowid,2)?;read.reserve_fields(&mut value.joints,rows.len())?;for row in rows{value.joints.push(read.index(row,3)?);}skins.as_mut().push(skin.take());}Ok(skins.take())}
